"""A castle-jump failure bound gives up an interim active order.

Owner report 2026-11-22: the field stayed on hold and no sortie started.
The active step was an interim (chart_adjust) order whose X-menu jump had
failed 71 times; only the menu_not_open branch abandoned, so the same jump
was retried forever while every plan order stayed pending.
"""
from docich.hanjuku_speedrun.hanjuku.flows import map as M
from docich.hanjuku_speedrun.hanjuku_screen import Screen


def test_an_interim_castle_jump_is_abandoned_after_the_bound():
    mem = {
        'tick': 100,
        'castle_jump': {'step': 'I:x', 'source': 'カストーラ', 'mode': 'source'},
        'castle_jump_menu_failures': {'I:x': 3},
        'plan': {'active': 'I:x', 'orders': {}},
        'chart_adjust': {
            'interim_order': {'step': 'I:x', 'source': 'カストーラ',
                              'target': 'スペンソニア', 'general': 'ビシソワーズ'},
            'interim_steps': {'attack|カストーラ|スペンソニア|ビシソワーズ': 'I:x'},
        },
        '_records': [],
    }
    screen = Screen([], None, '', kind='map')
    assert M._end_castle_jump(screen, mem, 'scroll_stalled') == []
    assert mem['plan']['active'] is None
    assert mem['plan']['orders']['I:x'] == 'failed'
    assert 'interim_order' not in mem['chart_adjust']
    assert mem['chart_adjust']['interim_steps'] == {}
    decisions = [r['decision'] for r in mem['_records']]
    assert 'chart_interim_abandoned' in decisions
    assert 'castle_jump_abandoned' in decisions
